@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1 class="mb-4">Course Catalog</h1>

    <form method="get" class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses, instructors..." />
        </div>
        <div class="col-md-4">
            <select name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in Catalog.GetDepartments())
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @{
        var courses = Catalog.SearchCourses(Search, DepartmentId);
    }

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses found matching your criteria.</div>
    }
    else
    {
        <p class="text-muted mb-3">Showing @courses.Count course(s)</p>
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in courses)
                    {
                        var dept = Catalog.GetDepartment(course.DepartmentId);
                        <tr>
                            <td>@course.CourseCode</td>
                            <td>@course.Title</td>
                            <td>@dept?.Name</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
                <strong>@(Catalog.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
            <p class="mb-0">You will receive a confirmation at your university email.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <p class="text-muted mb-4">Fill out this form to request enrollment in a course. All fields are required.</p>

        <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="row g-3" style="max-width: 600px;">
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="col-12">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                <ValidationMessage For="() => Model.StudentName" />
            </div>

            <div class="col-12">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., STU-12345" />
                <ValidationMessage For="() => Model.StudentId" />
            </div>

            <div class="col-12">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in Catalog.GetCourses())
                    {
                        <option value="@course.Id">@course.CourseCode — @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" />
            </div>

            <div class="col-12">
                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </div>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}

